contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // deposit1 and deposit2 are wei values to send in two separate calls
    function run(uint256 deposit1, uint256 deposit2) public {
        // require this contract has enough ether to forward both deposits
        require(address(this).balance >= deposit1 + deposit2);
        // first deposit
        c.addToBalance{value: deposit1}();
        // second deposit
        c.addToBalance{value: deposit2}();
        // observe balance recorded in C for this contract
        uint256 recorded = c.getBalance(address(this));
        // On the original contract, balances accumulate, so recorded >= deposit1 + deposit2
        // On the mutant that overwrites with msg.value, recorded == deposit2 which can be < sum
        assert(recorded >= deposit1 + deposit2);
    }

    // allow this test contract to receive ether to fund deposits
    receive() external payable {}
}

