pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: actor (address) and two amounts to allow establishing a prior balance and then adding more.
    function testFuzz_property(address actor, uint128 firstDeposit, uint128 secondDeposit) public {
        // Keep addresses and amounts in admissible wide domain
        vm.assume(actor != address(0));
        // avoid trivial zero amounts for clarity but allow zeros too
        uint256 a = uint256(firstDeposit);
        uint256 b = uint256(secondDeposit);

        // Fund the actor so they can send ETH
        vm.deal(actor, a + b + 1 ether);

        // 1) actor makes an initial deposit a
        vm.prank(actor);
        c.addToBalance{value: a}();

        // Record balance after first deposit (via getter)
        uint256 balanceAfterFirst = c.getBalance(actor);

        // 2) actor makes a second deposit b
        vm.prank(actor);
        c.addToBalance{value: b}();

        // The general rule (the correct contract satisfies this for all inputs):
        // final balance == balanceAfterFirst + b
        uint256 finalBalance = c.getBalance(actor);

        assertTrue(finalBalance == balanceAfterFirst + b);
    }
}

