pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: attacker address and an amount
    function testFuzz_property(address attacker, uint256 amount) public {
        // keep amount in a sensible range so vm.deal won't overflow and it's non-zero to exercise logic
        amount = bound(amount, 1, 1 ether);
        // attacker must be a contract with malicious fallback that will attempt reentrancy
        // deploy helper and fund it
        Attacker a = new Attacker(address(c));
        vm.deal(address(a), amount);

        // make the attacker call addToBalance sending `amount` from the attacker contract
        // attacker contract will in its receive() try to reenter withdrawBalance
        a.deposit{value: amount}();

        // After the single external call deposit() (which routes to c.addToBalance),
        // in the correct contract the attacker's recorded balance equals amount
        // (i.e., balance didn't get drained during the call). We assert that property.
        assertTrue(c.getBalance(address(a)) == amount);
    }
}

// Minimal attacker that on receiving ETH will attempt to reenter C.withdrawBalance
contract Attacker {
    address payable target;
    constructor(address _target) {
        target = payable(_target);
    }

    // deposit routes to addToBalance on C
    function deposit() external payable {
        // forward to C.addToBalance via low-level call to ensure we hit payable
        // C.addToBalance is public payable
        (bool ok, ) = target.call{value: msg.value}(abi.encodeWithSignature("addToBalance()"));
        require(ok);
    }

    // When receiving ETH (from C.withdrawBalance), attempt to reenter withdrawBalance
    receive() external payable {
        // attempt to reenter withdrawBalance; if the target is properly locked this will fail
        // but if the mutated modifier unlocked early this will succeed and drain funds
        // use low-level call to ignore revert or success; we don't care about outcome here
        (bool,) = target.call(abi.encodeWithSignature("withdrawBalance()"));
    }
}

