pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz the depositor and the deposit amount. The adversary is a reentrant attacker
    // whose receive() will call withdrawBalance() back into c if reentrancy is possible.
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero and amount in a sensible range but wide
        vm.assume(depositor != address(0));
        amount = bound(amount, 0, 1 ether);

        // fund the depositor so they can send value
        vm.deal(depositor, amount);

        // Deploy attacker helper that will attempt reentrancy on receive
        Attacker atk = new Attacker(c);

        // If depositor equals attacker address, use the attacker; otherwise we will have depositor send
        address payer = depositor;

        // First, deposit some funds for an unrelated address to ensure sum tracking.
        // Use a different address to observe total behavior: fund attacker a bit so it can be target of reentrancy
        vm.deal(address(atk), 0.1 ether);

        // Now perform the fuzzed deposit from depositor to c
        vm.startPrank(payer);
        // If depositor equals attacker contract, call from attacker; else normal EOA sending to addToBalance
        if (payer == address(atk)) {
            // attacker will send value and its receive may reenter if possible
            atk.doDeposit{value: amount}();
        } else {
            c.addToBalance{value: amount}();
        }
        vm.stopPrank();

        // General rule to assert: contract's on-chain ETH balance equals the sum of stored user balances observed via mapping getter for known addresses.
        // We cannot iterate all addresses, but for this contract the invariant implies that address(c).balance equals the stored sum; a conservative check is that address(c).balance == address(c).balance after reading explicit balances we can query.
        // We assert the concrete relation between stored balance of the depositor and the contract balance: the stored balance for depositor must never exceed address(c).balance.
        // This holds in the correct contract for all inputs; the mutant allowing reentrancy can cause stored balances to be drained while contract balance remains, violating monotonic relation.

        uint balDepositor = c.getBalance(payer);
        // single assertion reading c: in the correct contract, the depositor's stored balance is <= contract balance always
        assertTrue(balDepositor <= address(c).balance);
    }
}

// Minimal attacker that reenters on receive to call withdrawBalance()
contract Attacker {
    C target;
    constructor(C _t) payable {
        target = _t;
    }

    // initiate a deposit from this contract
    function doDeposit() external payable {
        target.addToBalance{value: msg.value}();
    }

    receive() external payable {
        // try to reenter withdrawBalance; if modifier is buggy, this will succeed and drain balances
        // we ignore success/failure
        (bool ok, ) = address(target).call(abi.encodeWithSignature("withdrawBalance()"));
        ok; // silence unused
    }
}

