pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed params: attacker address and deposit amount
    function testFuzz_property(address attacker, uint256 amount) public {
        // Keep amount in a reasonable nonzero range but wide enough to allow fuzzing
        vm.assume(attacker != address(0));
        amount = bound(amount, 1, 1 ether);

        // Deploy a reentrant attacker that will call back into c during receive()
        ReentrantAttacker a = new ReentrantAttacker(c);

        // Fund the attacker so it can make the deposit
        vm.deal(address(a), amount);

        // Perform the deposit from the attacker contract
        // The attacker will attempt to reenter and call withdrawBalance during the deposit
        a.doDeposit{value: amount}();

        // After addToBalance completes, the invariant for the correct contract is:
        // the stored userBalance for the attacker address (the attacker contract) equals the amount it deposited.
        // The buggy contract that unlocks before executing the body can let the attacker reenter and withdraw during
        // addToBalance, causing userBalance to be less than the deposited amount for some inputs.
        assertTrue(c.getBalance(address(a)) == amount);
    }
}

// Minimal reentrant attacker helper: when it receives ETH, it reenters c.withdrawBalance()
contract ReentrantAttacker {
    C immutable target;
    bool reentered;
    constructor(C _target) {
        target = _target;
        reentered = false;
    }

    // Called by the test to perform the deposit
    function doDeposit() external payable {
        // call C.addToBalance from this contract
        target.addToBalance{value: msg.value}();
    }

    // When receiving Ether, try to reenter once to withdraw
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // Attempt to reenter: call withdrawBalance on target
            // Ignoring success/failure; if reentrancy is possible this will drain balances
            // otherwise it will revert or do nothing
            target.withdrawBalance();
        }
    }
}

