pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker(address(c));
    }

    // fuzz parameters: depositor address (actor) and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor as a nonzero address and amount within reasonable gas/ETH bounds
        vm.assume(depositor != address(0));
        uint256 bounded = bound(amount, 1, 1 ether); // allow wide range but nonzero

        // fund depositor and attacker so they can make calls
        vm.deal(depositor, bounded + 1 ether);
        vm.deal(address(attacker), 1 ether);

        // make attacker configured to reenter into c during receive
        attacker.setVictim(address(c));

        // Have depositor call addToBalance but using attacker as intermediary caller: the attacker will forward the deposit
        // so that the contract sees msg.sender == address(attacker) during the deposit.
        // This models an external counterparty (attacker) that reenters when receiving ETH.

        // depositor funds attacker, then depositor triggers attacker's forward which calls c.addToBalance{value: bounded}()
        vm.prank(depositor);
        (bool sent,) = address(attacker).call{value: bounded}(
            abi.encodeWithSelector(Attacker.forwardDeposit.selector, depositor)
        );
        // ensure the forwarding call itself succeeded as an EOA->attacker call
        require(sent, "forward funding failed");

        // Now the attacker (as msg.sender) invoked c.addToBalance{value:bounded} and during that call may reenter
        // After the external call completes, read c.getBalance(address(attacker))

        uint256 stored = c.getBalance(address(attacker));

        // The reference contract guarantees that after addToBalance returns, the stored userBalance for the depositor
        // (here the actual caller to c was the attacker) is at least the amount that was deposited into c in that call.
        // The buggy mutant that unlocks the reentrancy guard early can reenter and withdraw during addToBalance,
        // making the stored balance for some address smaller than the deposit. We assert the universal property:
        assertTrue(stored >= bounded);
    }
}

// Minimal re-entrant-capable helper: it forwards deposits to victim and on receive tries to reenter withdrawBalance
contract Attacker {
    address public victim;
    constructor(address _v) payable {
        victim = _v;
    }
    function setVictim(address _v) public {
        victim = _v;
    }

    // Called by an EOA (the fuzzed depositor) with value; forwards the value to victim.addToBalance
    function forwardDeposit(address /*originalDepositor*/) public payable {
        // call victim.addToBalance with this contract as msg.sender so reentrancy is possible via receive
        C(victim).addToBalance{value: msg.value}();
    }

    // receive: when victim sends ETH to this contract during withdrawBalance, attempt reentry into victim.withdrawBalance
    receive() external payable {
        // attempt to reenter withdrawBalance; if reentrancy guard is broken this will succeed and reduce victim's stored balances
        // wrap in try/catch to avoid bubbling if it reverts on the correct contract
        try C(victim).withdrawBalance() {
            // ignore
        } catch {
            // ignore
        }
    }
}

