pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: depositor and deposit amount. We will deploy an attacker helper that will act as B.
    // General rule: for any depositor addr and any deposit amount > 0, if the deposit is routed through
    // an adversarial contract B that reenters to call withdrawBalance during its receive(), the correct
    // contract guarantees that after addToBalance returns the attacker's recorded balance has not decreased
    // compared to before the call. The mutant that unlocks early allows the reentrant withdraw to reduce B's balance
    // for some inputs; the fuzzer should find such inputs.
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor a real EOA and amount in a reasonable range but wide
        depositor = vm.addr(uint256(uint160(depositor)) | 1); // ensure non-zero address
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether); // wide enough to allow exploit

        // Deploy attacker helper B with reference to c
        AttackerHelper attacker = new AttackerHelper(c);

        // Fund depositor and attacker so they can send and attacker can reenter
        vm.deal(depositor, amount);
        vm.deal(address(attacker), 0);

        // Ensure attacker has some initial stored balance to see if it gets drained
        // Let attacker deposit a small amount first
        uint256 seedDeposit = 1 wei;
        vm.deal(address(attacker), seedDeposit);
        vm.prank(address(attacker));
        c.addToBalance{value: seedDeposit}();

        uint256 beforeAttackerBalance = c.getBalance(address(attacker));

        // Now perform the depositor's deposit but routed through attacker contract:
        // attacker will, in its payable fallback, reenter c.withdrawBalance() once.
        // We make depositor call attacker with value `amount`, so attacker receives funds and forwards them into c
        vm.prank(depositor);
        // call the attacker contract and give it ETH; attacker will in turn call c.addToBalance{value: amount}()
        (bool ok,) = address(attacker).call{value: amount}("");
        require(ok, "call to attacker failed");

        // After the routed deposit completes, in the correct contract the attacker's stored balance must be unchanged
        // (it cannot be drained by reentrancy during someone else's deposit). The mutant that unlocks early may allow
        // the attacker to reenter and withdraw its own stored balance, reducing it below beforeAttackerBalance for some inputs.
        uint256 afterAttackerBalance = c.getBalance(address(attacker));

        assertTrue(afterAttackerBalance >= beforeAttackerBalance, "attacker balance decreased (mutant detected)");
    }
}

// Minimal attacker helper: when called (with ETH) it forwards the ETH into c.addToBalance
// but during the forwarding it will reenter on receive() to call withdrawBalance once.
contract AttackerHelper {
    C immutable c;
    bool reentered;
    constructor(C _c) {
        c = _c;
        reentered = false;
    }

    // Fallback receives ETH; when invoked as part of forwarding a depositor's call, this is where reentrancy happens.
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // reenter to withdrawBalance; for the real contract this should be blocked by nonReentrant_
            // but the mutant that unlocks early would allow this and potentially drain attacker's stored balance
            // We ignore the return; using low-level call to catch revert differences would require try/catch,
            // but the withdrawal uses a revert on failure, so wrap in try/catch would be here if needed.
            try c.withdrawBalance() {
                // ignore
            } catch {
                // ignore revert
            }
        }
    }

    // When called by an external depositor with value, forward that value into c.addToBalance
    fallback() external payable {
        // forward all received ETH into c.addToBalance
        c.addToBalance{value: msg.value}();
    }
}

