        vm.deal(attackerAddr, amt * 2);
        vm.prank(attackerAddr);
        Attacker atk = new Attacker(c, other);

        // Attacker deposits amt into its userBalance
        vm.prank(attackerAddr);
        c.addToBalance{value: amt}();

        // Record other's balance before
        uint256 beforeOther = c.getBalance(other);

        // Now have attacker call withdrawBalance through the attacker contract which will re-enter once
        // The attacker contract was deployed by attackerAddr, so it has code and can receive funds
        // Provide the attacker contract enough ETH for any calls (it will receive the withdrawal)
        // Call withdrawBalance from the attacker contract (so msg.sender in C is attacker contract)
        vm.prank(attackerAddr);
        atk.triggerWithdraw{value: 0}();

        // Exactly one assertion: in the correct contract, other user's balance must not have increased
        uint256 afterOther = c.getBalance(other);
        assertTrue(afterOther == beforeOther);
    }
}

// Minimal attacker helper: on receiving funds, it attempts to re-enter C.withdrawBalance once
contract Attacker {
    C immutable target;
    address immutable other;
    bool reentered;
    constructor(C _target, address _other) payable {
        target = _target;
        other = _other;
        reentered = false;
    }

    // Called by test to initiate withdraw from this contract's context
    function triggerWithdraw() external {
        // This contract calls target.withdrawBalance() as if it were the depositor
        // But first ensure this contract has deposited some balance to be withdrawable
        // The test deposited into the attacker address and then deployed this contract from that address,
        // so attacker had done addToBalance as attackerAddr; we now call withdraw as this contract to route the call
        target.withdrawBalance();
    }

    // Receive funds and attempt a single re-entry into withdrawBalance to exploit ordering bug
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // re-enter target.withdrawBalance(); if bug exists, this can manipulate balances
            target.withdrawBalance();
        }
    }
}

