pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: depositor (actor who funds its balance), attacker initial balance to send, victim address
    function testFuzz_property(address depositor, uint128 depositAmount, address victim) public {
        // keep inputs in wide but sensible ranges
        vm.assume(depositor != address(0));
        vm.assume(victim != address(0));
        // ensure depositor and attacker are distinct to allow cross-account manipulation
        vm.assume(depositor != victim);
        // bound deposit amount to avoid overflow in test environment
        uint256 amt = uint256(depositAmount) % 1 ether;
        if (amt == 0) { amt = 1e15; } // at least some minimal value

        // fund depositor so it can call addToBalance
        vm.deal(depositor, amt);
        vm.prank(depositor);
        c.addToBalance{value: amt}();

        // Now deploy an attacker helper that will reenter withdrawBalance when receiving funds
        Attacker attacker = new Attacker(c);

        // fund attacker so it can be the caller of withdraw
        vm.deal(address(attacker), 0);

        // Give victim some balance as well, so reentrancy can try to drain victim
        // We make the depositor also set some balance for victim by impersonating victim depositing
        // (fuzzed victim may equal depositor avoided above)
        uint256 victimAmt = 1e15; // small amount for victim
        vm.deal(victim, victimAmt);
        vm.prank(victim);
        c.addToBalance{value: victimAmt}();

        // Now attempt withdrawal from attacker which will reenter and try to withdraw victim's balance
        // First, give attacker a small balance so withdraw sends Ether to attacker and triggers reentry
        vm.deal(address(attacker), 1);
        vm.prank(address(attacker));
        // call withdrawBalance on c from attacker; in the buggy mutant this reentrancy can drain victim
        try c.withdrawBalance{value: 0}() {
            // nothing
        } catch {
            // ignore revert - behavior difference is reflected in balances
        }

        // General property to assert: in the correct contract (with nonReentrant_) no other account's balance
        // was drained by this withdrawal attempt; i.e., victim's stored balance remains equal to the amount
        // they deposited.
        // This single assertTrue reads c.getBalance(victim) which the reference preserves for all inputs,
        // while the mutant (without nonReentrant_) will allow the attacker to reenter and make this fail for some fuzzed inputs.
        assertTrue(c.getBalance(victim) == victimAmt);
    }
}

// Attacker contract: when it receives Ether from withdrawBalance it immediately calls back into c.withdrawBalance()
contract Attacker {
    C public c;
    bool public first = true;
    constructor(C _c) {
        c = _c;
    }
    receive() external payable {
        // attempt reentrancy once to try to withdraw other balances
        if (first) {
            first = false;
            // reenter withdrawBalance; in the buggy contract this will be allowed and may drain others
            // use low-level call to ignore reverts
            (bool s,) = address(c).call(abi.encodeWithSelector(c.withdrawBalance.selector));
            s; // silence
        }
    }
}
